namespace sv_694200b722b3402bbac0d7c78c987148.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts for the current warehouse.
/// Components subscribe to <see cref="OnAlertCountChanged"/> to stay in sync.
/// Polling is driven by the Dashboard page; when new data arrives every subscriber
/// (sidebar badge, dashboard panel, etc.) is notified — not just the poller.
/// </summary>
public class InventoryAlertService
{
    private static readonly Random _random = new();

    public int CurrentAlertCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query that returns low-stock item count for a warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count = _random.Next(0, 16); // 0–15 inclusive
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest count and notifies ALL subscribers so every component updates.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }
}

