@using sv_694200b722b3402bbac0d7c78c987148.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm w-auto" value="@WarehouseState.Current.Id"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseState.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
            // Immediately refresh alerts for the newly selected warehouse
            await AlertService.RefreshAlertCountAsync(WarehouseState.Current.Id);
        }
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        // Re-render if another component changes the warehouse
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    public void Dispose() => WarehouseState.OnChange -= _handler;
}

