@page "/dashboard"
@using sv_694200b722b3402bbac0d7c78c987148.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@attribute [StreamRendering]
@rendermode InteractiveServer

<PageTitle>Dashboard – @WarehouseState.Current.Name</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 30rem;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.Current.Name</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge @BadgeClass fs-6">@AlertService.CurrentAlertCount</span>
        </p>
        <p class="text-body-secondary small mb-0">
            Polling every 10 s · Last check: @_lastCheck.ToString("T")
        </p>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private DateTime _lastCheck = DateTime.Now;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(() =>
        {
            _lastCheck = DateTime.Now;
            StateHasChanged();
        });
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Fetch initial count then start background polling
            await AlertService.RefreshAlertCountAsync(WarehouseState.Current.Id);
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await AlertService.RefreshAlertCountAsync(WarehouseState.Current.Id);
            }
        }
        catch (OperationCanceledException) { }
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    private string BadgeClass =>
        AlertService.CurrentAlertCount > 0 ? "text-bg-danger" : "text-bg-secondary";

    public void Dispose()
    {
        StopPolling();
        WarehouseState.OnChange -= _warehouseHandler;
        AlertService.OnAlertCountChanged -= _alertHandler;
    }
}

